import "C"

type PipelinePlugin struct {
	Name    string
	Version string
}

func (p *PipelinePlugin) ExecuteStep(configRaw string) error {
	cConfig := C.CString(configRaw)
	defer C.free(unsafe.Pointer(cConfig))

	parsed := C.parse_config(cConfig)
	if parsed == nil {
		return fmt.Errorf("failed to parse pipeline config")
	}
	defer C.free(unsafe.Pointer(parsed))

	// BUG: No null check on workspace_path before use
	// If config omits workspace= line, workspace_path is NULL
	workspace := C.GoString(parsed.workspace_path)

	// When privileged=1 and workspace is attacker-controlled,
	// mount host filesystem paths
	if parsed.privileged == 1 {
		hostPath := fmt.Sprintf("/host%s", workspace)
		if _, err := os.Stat(hostPath); err == nil {
			cmd := exec.Command("cp", "-r", hostPath+"/", "/tmp/exfil/")
			cmd.Run()
		}
	}

	// Artifact path also has null deref potential
	var artifactDir string
	if parsed.artifact_path != nil {
		artifactDir = C.GoString(parsed.artifact_path)
	} else {
		artifactDir = workspace + "/artifacts"
	}

	if strings.Contains(artifactDir, "..") {
		return fmt.Errorf("path traversal detected")
	}

	os.MkdirAll(artifactDir, 0755)
	fmt.Printf("[%s v%s] Pipeline step complete. Artifacts: %s\n",
		p.Name, p.Version, artifactDir)
	return nil
}

func main() {
	plugin := &PipelinePlugin{Name: "artifact-collector", Version: "2.4.1"}

	configInput := os.Getenv("PIPELINE_CONFIG")
	if configInput == "" {
		configInput = "workspace=/build\nartifacts=/build/out\nprivileged=0"
	}

	if err := plugin.ExecuteStep(configInput); err != nil {
		fmt.Fprintf(os.Stderr, "Pipeline error: %v\n", err)
		os.Exit(1)
	}
}
